  const bad = (msg) => new Response(inquireForm({ values, notice: msg, err: true }), { status: 400, headers: NOSTORE });
  if (f("website", 10)) return new Response(inquireForm({ notice: "Thanks — your inquiry is on its way." }), { headers: NOSTORE });
